function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw dog
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 60);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 60);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 80);
  ctx.stroke();

  // draw tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 80);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 30, H/2 + 100);
  ctx.stroke();

  // draw ears
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 15, H/2 - 10);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 30, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 + 15, H/2 - 10);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 30, H/2 - 30);
  ctx.stroke();

  ctx.restore();
}
